-- DU FBS Economics sprint sets (Set 1 = 16 Qs, Set 2 = 25 Qs).
-- Paste into the Turso dashboard SQL console and run. Safe to re-run: skips anything already inserted.
-- Sets are created as 'draft'; activate them from /admin/sprint.

-- Economics Set 1
INSERT INTO sprint_sets (subject, title, status) SELECT 'economics', 'Economics Set 1', 'draft' WHERE NOT EXISTS (SELECT 1 FROM sprint_sets WHERE subject = 'economics' AND title = 'Economics Set 1');
WITH v(number, stem, options, correct_key) AS (VALUES
  (1, 'What happens to the equilibrium price when there is an increase in demand, assuming supply remains constant?', '[{"key": "A", "text": "It decreases"}, {"key": "B", "text": "It remains the same"}, {"key": "C", "text": "It increases"}, {"key": "D", "text": "It becomes zero"}]', 'C'),
  (2, 'Which of the following is NOT a determinant of supply?', '[{"key": "A", "text": "Technology"}, {"key": "B", "text": "Cost of production"}, {"key": "C", "text": "Income of consumers"}, {"key": "D", "text": "Number of producers"}]', 'C'),
  (3, 'GDP is the sum of:', '[{"key": "A", "text": "Private consumption, investment, government spending, and net exports"}, {"key": "B", "text": "Only exports and imports"}, {"key": "C", "text": "Tax revenues and government spending"}, {"key": "D", "text": "National income and depreciation"}]', 'A'),
  (4, 'Which policy tool is used to control inflation?', '[{"key": "A", "text": "Increasing government expenditure"}, {"key": "B", "text": "Reducing interest rates"}, {"key": "C", "text": "Reducing money supply"}, {"key": "D", "text": "Increasing tax rates on exports"}]', 'C'),
  (5, 'A perfectly inelastic demand curve is represented by:', '[{"key": "A", "text": "A horizontal line"}, {"key": "B", "text": "A vertical line"}, {"key": "C", "text": "A downward-sloping curve"}, {"key": "D", "text": "An upward-sloping curve"}]', 'B'),
  (6, 'Which market structure is characterized by many sellers and differentiated products?', '[{"key": "A", "text": "Perfect competition"}, {"key": "B", "text": "Monopolistic competition"}, {"key": "C", "text": "Oligopoly"}, {"key": "D", "text": "Monopoly"}]', 'B'),
  (7, 'The theory of comparative advantage was introduced by:', '[{"key": "A", "text": "Adam Smith"}, {"key": "B", "text": "David Ricardo"}, {"key": "C", "text": "John Maynard Keynes"}, {"key": "D", "text": "Milton Friedman"}]', 'B'),
  (8, 'A tariff is:', '[{"key": "A", "text": "A tax on domestic goods"}, {"key": "B", "text": "A subsidy for exports"}, {"key": "C", "text": "A tax on imported goods"}, {"key": "D", "text": "A quota on imports"}]', 'C'),
  (9, 'Which of the following is correct in the case of Giffen Goods?', '[{"key": "A", "text": "Both income effect and substitution effect are negative"}, {"key": "B", "text": "Positive substitute effect is greater than negative income effect"}, {"key": "C", "text": "Negative income effect is greater than positive substitution effect"}, {"key": "D", "text": "Positive income effect is greater than negative substitution effect"}]', 'C'),
  (10, 'The price elasticity of demand for a product will be greater when:', '[{"key": "A", "text": "The product is a necessity"}, {"key": "B", "text": "There are fewer substitutes available"}, {"key": "C", "text": "The product has many close substitutes"}, {"key": "D", "text": "The time available for adjustment is short"}]', 'C'),
  (11, 'Which market structure is characterized by a unique product with no close substitutes?', '[{"key": "A", "text": "Perfect competition"}, {"key": "B", "text": "Monopoly"}, {"key": "C", "text": "Oligopoly"}, {"key": "D", "text": "Monopolistic competition"}]', 'B'),
  (12, 'Which of the following is a feature of perfect competition?', '[{"key": "A", "text": "Product differentiation"}, {"key": "B", "text": "High barriers to entry"}, {"key": "C", "text": "Price-taking behavior"}, {"key": "D", "text": "Few sellers"}]', 'C'),
  (13, 'Transfer payment is excluded in national income accounting because:', '[{"key": "A", "text": "It is not related to production"}, {"key": "B", "text": "It is of negligible amount"}, {"key": "C", "text": "It is a source of double counting"}, {"key": "D", "text": "It was counted previously"}]', 'A'),
  (14, 'Which component is not part of Aggregate Demand (AD)?', '[{"key": "A", "text": "Consumption (C)"}, {"key": "B", "text": "Investment (I)"}, {"key": "C", "text": "Savings (S)"}, {"key": "D", "text": "Net exports (NX)"}]', 'C'),
  (15, 'A decrease in the general price level is referred to as:', '[{"key": "A", "text": "Deflation"}, {"key": "B", "text": "Inflation"}, {"key": "C", "text": "Disinflation"}, {"key": "D", "text": "Stagflation"}]', 'A'),
  (16, 'Which of the following is an example of fiscal policy?', '[{"key": "A", "text": "Changing the money supply"}, {"key": "B", "text": "Increasing interest rates"}, {"key": "C", "text": "Decreasing government spending"}, {"key": "D", "text": "Adjusting exchange rates"}]', 'C')
)
INSERT INTO sprint_questions (set_id, number, stem, options, correct_key, explanation)
SELECT s.id, v.number, v.stem, v.options, v.correct_key, NULL FROM sprint_sets s, v
WHERE s.subject = 'economics' AND s.title = 'Economics Set 1'
  AND NOT EXISTS (SELECT 1 FROM sprint_questions WHERE set_id = s.id);

-- Economics Set 2
INSERT INTO sprint_sets (subject, title, status) SELECT 'economics', 'Economics Set 2', 'draft' WHERE NOT EXISTS (SELECT 1 FROM sprint_sets WHERE subject = 'economics' AND title = 'Economics Set 2');
WITH v(number, stem, options, correct_key) AS (VALUES
  (1, 'What is the basic economic problem?', '[{"key": "A", "text": "The coexistence of unemployment and inflation"}, {"key": "B", "text": "The unlimited wants exceeding scarce resources"}, {"key": "C", "text": "The imbalance between savings and investments"}, {"key": "D", "text": "The inability to determine opportunity costs"}]', 'B'),
  (2, 'Which of the following is a feature of Giffen goods?', '[{"key": "A", "text": "Demand decreases as price decreases"}, {"key": "B", "text": "Demand increases as price decreases"}, {"key": "C", "text": "Demand increases as price increases"}, {"key": "D", "text": "Demand remains constant regardless of price"}]', 'C'),
  (3, 'What is the primary aim of a rational consumer?', '[{"key": "A", "text": "To maximize profits"}, {"key": "B", "text": "To minimize costs"}, {"key": "C", "text": "To maximize utility"}, {"key": "D", "text": "To maximize savings"}]', 'C'),
  (4, 'Which of the following is NOT a function of price?', '[{"key": "A", "text": "Signaling function"}, {"key": "B", "text": "Rationing function"}, {"key": "C", "text": "Incentive function"}, {"key": "D", "text": "Preservation function"}]', 'D'),
  (5, 'What is the Price Elasticity of Demand (PED) when a price increase from $10 to $12 causes demand to drop from 500 units to 400 units?', '[{"key": "A", "text": "0.8"}, {"key": "B", "text": "1.2"}, {"key": "C", "text": "1.5"}, {"key": "D", "text": "2.0"}]', 'D'),
  (6, 'Which of the following factors is unlikely to directly affect supply?', '[{"key": "A", "text": "Cost of production"}, {"key": "B", "text": "Consumer preferences"}, {"key": "C", "text": "Technology"}, {"key": "D", "text": "Natural factors"}]', 'B'),
  (7, 'What type of goods are street lights classified as?', '[{"key": "A", "text": "Public goods"}, {"key": "B", "text": "Private goods"}, {"key": "C", "text": "Consumer goods"}, {"key": "D", "text": "Capital goods"}]', 'A'),
  (8, 'Which economic agent primarily aims to maximize societal welfare?', '[{"key": "A", "text": "Consumers"}, {"key": "B", "text": "Firms"}, {"key": "C", "text": "Governments"}, {"key": "D", "text": "Entrepreneurs"}]', 'C'),
  (9, 'Which type of economic system relies completely on market forces for resource allocation?', '[{"key": "A", "text": "Command economy"}, {"key": "B", "text": "Mixed economy"}, {"key": "C", "text": "Free market economy"}, {"key": "D", "text": "Socialist economy"}]', 'C'),
  (10, 'Who is considered the ''Father of Division of Labour''?', '[{"key": "A", "text": "John Maynard Keynes"}, {"key": "B", "text": "Adam Smith"}, {"key": "C", "text": "Karl Marx"}, {"key": "D", "text": "David Ricardo"}]', 'B'),
  (11, 'What distinguishes labor-intensive from capital-intensive production techniques?', '[{"key": "A", "text": "Use of natural resources"}, {"key": "B", "text": "Proportion of labor vs. machinery"}, {"key": "C", "text": "Level of government intervention"}, {"key": "D", "text": "Duration of the production process"}]', 'B'),
  (12, 'What does the law of diminishing marginal utility imply?', '[{"key": "A", "text": "Marginal utility increases as more units of a product are consumed"}, {"key": "B", "text": "Total utility always decreases with additional consumption"}, {"key": "C", "text": "Marginal utility decreases as more units of a product are consumed"}, {"key": "D", "text": "Total utility becomes zero after a certain point"}]', 'C'),
  (13, 'Which of the following is NOT a factor of production?', '[{"key": "A", "text": "Land"}, {"key": "B", "text": "Knowledge"}, {"key": "C", "text": "Profit"}, {"key": "D", "text": "Labour"}]', 'C'),
  (14, 'What is the opportunity cost of an economic decision?', '[{"key": "A", "text": "The total expenditure incurred"}, {"key": "B", "text": "The next best alternative forgone"}, {"key": "C", "text": "The cost of raw materials used"}, {"key": "D", "text": "The savings generated from the decision"}]', 'B'),
  (15, 'In which time period are all factors of production variable?', '[{"key": "A", "text": "Immediate run"}, {"key": "B", "text": "Short run"}, {"key": "C", "text": "Long run"}, {"key": "D", "text": "Fixed run"}]', 'C'),
  (16, 'Which of the following scenarios illustrates the concept of a Giffen good?', '[{"key": "A", "text": "A luxury watch''s demand increases as its price rises due to its status symbol."}, {"key": "B", "text": "Demand for bread increases among low-income households despite a price hike."}, {"key": "C", "text": "A decrease in the price of rice leads to a significant rise in its demand."}, {"key": "D", "text": "A fall in the price of a product leads to a decrease in its demand."}]', 'B'),
  (17, 'If the Price Elasticity of Demand (PED) for a product is 0.5, which of the following is true?', '[{"key": "A", "text": "The product is price elastic, and a price decrease will lead to a proportionally larger increase in demand."}, {"key": "B", "text": "The product is price inelastic, and a price increase will lead to a proportionally smaller decrease in demand."}, {"key": "C", "text": "The product is unit elastic, and any price change will lead to a proportional change in demand."}, {"key": "D", "text": "The product is perfectly inelastic, and demand will remain unchanged regardless of price changes."}]', 'B'),
  (18, 'What is the significance of the rationing function of price in an economy?', '[{"key": "A", "text": "It signals producers to increase supply due to high demand."}, {"key": "B", "text": "It prevents resource allocation in the production of demerit goods."}, {"key": "C", "text": "It allocates scarce resources to those willing and able to pay the most."}, {"key": "D", "text": "It ensures government regulation of market prices."}]', 'C'),
  (19, 'In a command economy, which of the following would most likely occur?', '[{"key": "A", "text": "Resources are allocated based on consumer preferences."}, {"key": "B", "text": "Prices are determined by the forces of demand and supply."}, {"key": "C", "text": "Public goods and merit goods are provided efficiently and equitably."}, {"key": "D", "text": "Private ownership of resources dominates resource allocation."}]', 'C'),
  (20, 'Which factor would increase the Price Elasticity of Supply (PES) for a product?', '[{"key": "A", "text": "The product is highly perishable, like fresh fruits."}, {"key": "B", "text": "The production process requires significant time to adjust output."}, {"key": "C", "text": "The availability of idle production capacity in the industry."}, {"key": "D", "text": "Legal constraints make it difficult to increase supply quickly."}]', 'C'),
  (21, 'How does the division of labor contribute to higher productivity in a specialized economy?', '[{"key": "A", "text": "It reduces the need for interdependence among workers."}, {"key": "B", "text": "It allows workers to focus on simpler tasks, increasing efficiency."}, {"key": "C", "text": "It eliminates the need for technological advancements."}, {"key": "D", "text": "It minimizes the risk of unemployment in highly skilled sectors."}]', 'B'),
  (22, 'Which of the following accurately defines "money is what money does," as per John K. Galbraith?', '[{"key": "A", "text": "Money derives its value from the gold standard."}, {"key": "B", "text": "Money''s definition is based solely on its physical attributes."}, {"key": "C", "text": "Money''s role and function are defined by its practical usage in an economy."}, {"key": "D", "text": "Money''s theoretical definition is more important than its application."}]', 'C'),
  (23, 'A rise in indirect taxes on a product will most likely lead to which of the following outcomes?', '[{"key": "A", "text": "Increase in supply as producers earn higher profits."}, {"key": "B", "text": "Shift in the supply curve to the left due to higher production costs."}, {"key": "C", "text": "Increase in consumer demand due to price incentives."}, {"key": "D", "text": "Increase in the availability of substitute goods."}]', 'B'),
  (24, 'Which of the following correctly matches the function of money with its description?', '[{"key": "A", "text": "Medium of Exchange – Allows for the accumulation of wealth over time."}, {"key": "B", "text": "Store of Value – Provides a standard for measuring the value of goods and services."}, {"key": "C", "text": "Measure of Value – Enables deferred payments and credit transactions."}, {"key": "D", "text": "Method of Deferred Payment – Facilitates transactions that will occur in the future."}]', 'D'),
  (25, 'Why do free goods not face the problem of scarcity?', '[{"key": "A", "text": "They are allocated by the government for equitable distribution."}, {"key": "B", "text": "Their production does not require any factors of production."}, {"key": "C", "text": "They exist in unlimited supply and are abundantly available without cost."}, {"key": "D", "text": "Their consumption leads to a decrease in demand over time."}]', 'C')
)
INSERT INTO sprint_questions (set_id, number, stem, options, correct_key, explanation)
SELECT s.id, v.number, v.stem, v.options, v.correct_key, NULL FROM sprint_sets s, v
WHERE s.subject = 'economics' AND s.title = 'Economics Set 2'
  AND NOT EXISTS (SELECT 1 FROM sprint_questions WHERE set_id = s.id);
